import{z as s,x as i,o as e,c as d,q as l,j as t,D as A,d as B,s as o,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"性能回归的方法","description":"","frontmatter":{"title":"性能回归的方法","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-perf-regression.md","filePath":"llm/fw-perf-regression.md","lastUpdated":1791413859000}'),D={name:"llm/fw-perf-regression.md"};function p(C,E,m,F,h,f){const r=i("Mermaid");return e(),d("div",null,[E[2]||(E[2]=l('<h1 id="性能回归的方法" tabindex="-1">性能回归的方法 <a class="header-anchor" href="#性能回归的方法" aria-label="Permalink to &quot;性能回归的方法&quot;">​</a></h1><div class="epigraph"><p>源码走读的最后一关不是读懂，而是证明：你的改动让系统变快了，而且快得不是噪声。</p><footer>—— 据 vLLM 与 SGLang 基准脚本、llama-bench 文档及各仓库贡献指南整理</footer></div><p><a href="/llm/fw-kv-abstraction-comparison">上一课</a>以「账本定生死」收拢三课对照。走读之后必然动手，动手之后必须报数，本课写怎么报数才不作弊。方法面已有两块基石：内核级的压测设计见 <a href="/llm/ak-benchmark-methodology">内核基准方法论</a>，服务指标的合同口径——双分位数、goodput——见 <a href="/llm/sch-basics-metrics">调度基础与指标</a>。本课把它们接到<strong>仓库场景</strong>：给一个活跃的开源推理框架做改动前后的 A/B，以各仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>框架性能数字的默认状态是不可比。基准脚本各带默认参数：输入输出长度、请求到达方式、预热轮数、图捕获与编译开关，任何一个默认值变了，吞吐就动。更麻烦的是协变量：同一台机器上批大小随显存水位漂、tokenizer 版本不同导致同一段文本 token 数不同、OpenAI 兼容端点与原生接口的协议开销不同。拿两个版本各跑一次比大小，等于把八协变量装进一个百分比里。回归方法的全部工作是把协变量钉死，让唯一差异落在改动上。</p><h3 id="钉什么" tabindex="-1">钉什么 <a class="header-anchor" href="#钉什么" aria-label="Permalink to &quot;钉什么&quot;">​</a></h3><p>固定四层。硬件层：同机、同驱动、同显存余量，独占实例，别和别人的任务拼卡。负载层：锁死输入输出长度分布或用固定数据集、到达过程（固定速率还是泊松）、并发数与总请求数；基准脚本把这些写成参数，逐项显式给值，不用默认。系统层：预热到稳态、锁随机种子、记下图捕获与编译开关、量化和注意力后端配置——上一课的账本与插座差异都会从这里漏进来。统计层：每档跑足重复次数，报中位数与分位数区间而不是单次均值，见指标课的双分位合同。</p><p><span class="marginnote">术语翻译「预热到稳态」：进程刚启动的头几步要做懒加载、JIT 编译、显存池初始化，速度远低于正常运行。就像汽车冷启动油耗偏高——上来就测的是「冷车数据」，不是日常水平。先空跑几十上百个请求把系统「跑热」，再开始正式记录。</span></p>',8)),(e(),t(n,null,{default:A(()=>[o(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E6%94%B9%E5%8A%A8%22%5D%20--%3E%20CFG%5B%22%E5%9B%BA%E5%AE%9A%E5%8D%8F%E8%AE%AE%EF%BC%9A%E7%A1%AC%E4%BB%B6%20%2F%20%E8%B4%9F%E8%BD%BD%20%2F%20%E7%B3%BB%E7%BB%9F%E5%BC%80%E5%85%B3%22%5D%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20RUN%5B%22%E5%90%8C%E5%8D%8F%E8%AE%AE%E5%8F%8C%E8%B7%91%EF%BC%8C%E9%87%8D%E5%A4%8D%E5%A4%9A%E6%AC%A1%22%5D%0A%20%20NEW%5B%22%E6%94%B9%E5%8A%A8%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20RUN%0A%20%20RUN%20--%3E%20STAT%5B%22%E5%88%86%E5%B8%83%E6%AF%94%E8%BE%83%EF%BC%9A%E4%B8%AD%E4%BD%8D%E6%95%B0%20%2B%20%E5%88%86%E4%BD%8D%E5%8C%BA%E9%97%B4%22%5D%0A%20%20STAT%20--%3E%7C%E5%B7%AE%E5%BC%82%E8%B6%85%E5%87%BA%E5%99%AA%E5%A3%B0%E9%98%88%E5%80%BC%7C%20BISECT%5B%22%E4%BA%8C%E5%88%86%E5%AE%9A%E4%BD%8D%E5%BC%95%E5%85%A5%E7%82%B9%22%5D%0A%20%20STAT%20--%3E%7C%E5%B7%AE%E5%BC%82%E5%9C%A8%E5%99%AA%E5%A3%B0%E5%86%85%7C%20NOISE%5B%22%E5%88%A4%E5%AE%9A%E6%97%A0%E5%8F%AF%E6%8A%A5%E5%B7%AE%E5%BC%82%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"仓库基准脚本的默认输出常是均值加单次运行——这对回归判定几乎无用：服务端长尾来自批组成与到达抖动，均值会把它抹平。报数前先改统计口径，与报数本身同样重要。")],-1)),E[4]||(E[4]=a("h2",{id:"方法",tabindex:"-1"},[B("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[5]||(E[5]=a("p",null,[B("流程上分三步。第一步立基线：改动前的提交在同一协议下跑出分布，基线与实验必须"),a("strong",null,"同日同机"),B("，跨日机器状态会漂。第二步双盲比较：不看绝对值看分布，差异超出噪声带才算数；噪声带由重复实验自己估计，不拍脑袋。第三步归因：确认回归后，用二分法在提交历史里定位引入点，定位时再回到走读方法——先看改动落在哪一层，调度、插座还是账本，再预测它该在哪个指标上显形：调度改动先看排队与步时延，内核改动先看单步延迟，账本改动先看水位与命中率。指标与层次对不上，先怀疑测量而不是怀疑系统。")],-1)),(e(),t(n,null,{default:A(()=>[o(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E5%AE%9A%E4%BD%8D%E4%B8%80%E4%B8%AA%E6%80%A7%E8%83%BD%E6%94%B9%E5%8A%A8%2F%E5%9B%9E%E5%BD%92%22%5D%20--%3E%20Q%7B%22%E6%94%B9%E5%8A%A8%E8%90%BD%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%B0%83%E5%BA%A6%E5%99%A8%22%7C%20L1%5B%22%E6%8E%92%E9%98%9F%E6%97%B6%E5%BB%B6%E3%80%81%E6%AD%A5%E6%97%B6%E5%BB%B6%E3%80%81%E6%89%B9%E7%BB%84%E6%88%90%22%5D%0A%20%20Q%20--%3E%7C%22%E5%86%85%E6%A0%B8%2F%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%8F%92%E5%BA%A7%22%7C%20L2%5B%22%E5%8D%95%E6%AD%A5%E5%BB%B6%E8%BF%9F%E3%80%81%E6%AF%8F%20token%20%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20Q%20--%3E%7C%22KV%20%E8%B4%A6%E6%9C%AC%22%7C%20L3%5B%22%E6%98%BE%E5%AD%98%E6%B0%B4%E4%BD%8D%E3%80%81%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%E7%8E%87%E3%80%81%E6%8A%A2%E5%8D%A0%E6%AC%A1%E6%95%B0%22%5D%0A%20%20L1%20--%3E%20P%5B%22%E9%A2%84%E6%B5%8B%E7%9A%84%E6%8C%87%E6%A0%87%E5%BA%94%E6%98%BE%E5%BD%A2%22%5D%0A%20%20L2%20--%3E%20P%0A%20%20L3%20--%3E%20P%0A%20%20P%20--%3E%20V%7B%22%E5%AF%B9%E4%B8%8A%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20V%20--%20%22%E6%B2%A1%E5%AF%B9%E4%B8%8A%22%20--%3E%20SUS%5B%22%E5%85%88%E6%80%80%E7%96%91%E6%B5%8B%E9%87%8F%E5%8D%8F%E8%AE%AE%EF%BC%8C%E5%86%8D%E6%80%80%E7%96%91%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20V%20--%20%22%E5%AF%B9%E4%B8%8A%E4%BA%86%22%20--%3E%20OK%5B%22%E5%BD%92%E5%9B%A0%E6%88%90%E7%AB%8B%EF%BC%8C%E5%87%BA%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这套流程的机制根据是<strong>方差比效应更便宜</strong>。性能效应通常只有几个百分点，而服务端单次测量的方差轻松超过它；唯一划算的办法是压方差：固定协议压系统方差，重复采样压随机方差，分位数保住长尾不被均值吞掉。各仓库把这套东西半自动化了——服务级压测脚本产出吞吐与分位延迟报告，单机基准工具产出每 token 延迟，贡献指南把「附性能数据」写成大型改动的门槛——自动化的是跑，钉协议的仍是人。这也是为什么上一课的走读是性能工作的前置：不知道改动落在哪层，就不知道该盯哪个指标、钉哪些协变量。</p><p><span class="marginnote">数字实例：你的优化预期带来 3% 提升，而同协议重复 10 次的吞吐在 4800–5300 token/s 之间晃（±5%）。单跑一次新旧各一跑出的「+8%」多半是噪声撞上的。想分辨 3% 的效应，噪声带必须先压到 1–2% 以内——这就是「钉协议比效应本身更贵」的意思：效应越小，钉协议与重复采样的成本越高。</span></p><p><span class="marginnote">直觉类比「噪声带」：像用家用体重秤称一封信——秤本身每次读数会差半斤，信只有二两重，单次读数毫无意义。先把秤的抖动范围（噪声带）测出来，信的重量必须超过抖动才能被「看见」。性能基准同理：先量化系统自己的抖动，再谈改动带来了什么。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跨仓库横评不在本课范围：默认参数、协议与版本三方不对齐，横评数字没有解释力，跨硬件的方法另见 <a href="/llm/accelerator-comparison-method">加速器比较方法</a>。内核微基准与端到端服务压测是两层证据，不能互相替代，方法细节在内核方法论课。仓库的基准脚本本身也在演进，参数名以仓库当时状态为准；对只改文档、只改测试的贡献，性能门槛不适用，这引出最后一课的贡献流程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>框架性能默认不可比：脚本默认参数与硬件、负载、开关、统计四层协变量必须显式钉死。</li><li>基线与实验同日同机同协议，报中位数与分位区间，噪声带由重复实验自估。</li><li>回归确认后二分定位，归因时先按改动层次预测指标：调度看排队与步时延，内核看单步，账本看水位与命中率。</li><li>方差比效应更便宜是全部机制的根：压方差的三件套是固定协议、重复采样、分位数。</li><li>跨仓库横评无解释力，两层证据不可互替；脚本参数以仓库当时状态为准。</li><li>出处：vLLM 与 SGLang 基准脚本、llama-bench 与各仓库贡献指南，按实践整理。</li></ul>',8))])}const T=s(D,[["render",p]]);export{u as __pageData,T as default};
